<h4 class="mb-3">Reports</h4>
<div class="row g-3 mb-4"><?php foreach ($groups as $g => $items): ?><div class="col-md-6 col-lg-4"><div class="card h-100"><div class="card-header"><b><?= e($g) ?></b></div><div class="list-group list-group-flush"><?php foreach ($items as $k => $t): ?><a class="list-group-item list-group-item-action" href="<?= url('reports/view', ['report' => $k]) ?>"><i class="bi bi-bar-chart-line me-1"></i><?= e($t) ?></a><?php endforeach; ?></div></div></div><?php endforeach; ?></div>
<?php if (Auth::can('admin.reports.export')): ?><div class="card"><div class="card-header">Scheduled e-mail reports (CSV)</div><div class="card-body">
<form method="post" action="<?= url('reports/schedule') ?>" class="row g-2 mb-3 needs-validation" novalidate><?= csrf_field() ?><div class="col-md-4"><select name="report" class="form-select" required><option value="">Report...</option><?php foreach ($defs as $k => $d): ?><option value="<?= e($k) ?>"><?= e($d[0]) ?></option><?php endforeach; ?></select></div><div class="col-md-3"><input type="email" name="email" class="form-control" placeholder="Send to email" required></div><div class="col-md-2"><select name="frequency" class="form-select"><option value="daily">Daily</option><option value="weekly">Weekly</option><option value="monthly">Monthly</option></select></div><div class="col-auto"><button class="btn btn-primary">Schedule</button></div></form>
<table class="table table-sm mb-0"><tbody><?php foreach ($sched as $s): ?><tr><td><?= e($defs[$s['report']][0] ?? $s['report']) ?></td><td><?= e($s['frequency']) ?></td><td><?= e($s['email']) ?></td><td><?= e($s['last_run'] ?: 'never run') ?></td><td class="text-end"><form method="post" action="<?= url('reports/unschedule') ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$s['id'] ?>"><button class="btn btn-sm btn-outline-danger"><i class="bi bi-trash"></i></button></form></td></tr><?php endforeach; ?></tbody></table></div></div><?php endif; ?>
